# AI Office Self-Hosting Part D Model Routing Hybrid Execution Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\self-hosting-part-d-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @(
 "config\self-hosting",
 "workspace\self-hosting\routing-decisions",
 "workspace\self-hosting\hybrid-results",
 "workspace\templates",
 "scripts\self-hosting",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\self-hosting\hybrid-routing-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\self-hosting\routing-decision-schema.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\self-hosting\hybrid-execution-result-schema.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\self-hosting-routing-decision-template.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\self-hosting-hybrid-execution-result-template.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\AIOfficeHybridRouting.Common.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Get-AIOfficeModelRoutingDecision.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Invoke-AIOfficeHybridInference.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Get-AIOfficeHybridRoutingStatus.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Test-AIOfficeHybridRouting.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\Self-Hosted-AI-Office-Part-D-Model-Routing-Hybrid-Execution.md" -Base64Content ""
$Scripts = @(
 "E:\AI\AI-Office\scripts\self-hosting\AIOfficeHybridRouting.Common.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Get-AIOfficeModelRoutingDecision.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Invoke-AIOfficeHybridInference.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Get-AIOfficeHybridRoutingStatus.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Test-AIOfficeHybridRouting.ps1"
)
foreach ($ScriptPath in $Scripts) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $ScriptPath + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; ")) }
}
Write-Host ""
Write-Host "Self-Hosted AI Office Part D Model Routing and Hybrid Execution installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan